  add(codexHasHook ? "ok" : "fail", "Codex hooks", codexHasHook ? `${codexHooks} contains ${codexHook}` : existsSync9(codexHooks) ? `${codexHooks} missing CCR hook entry` : `${codexHooks} not found`);
